package com.example.rokidgeminisecretary;
import android.content.*;import android.content.res.*;import android.graphics.*;import android.util.Base64;import org.json.*;import java.io.*;import java.lang.reflect.*;
public final class TopicPayloadDeviceChecks {
 static int n;static void ok(boolean b,String why){n++;if(!b)throw new AssertionError(why);}
 public static int run(Context original,String apk)throws Exception{
  AssetManager assets=AssetManager.class.getConstructor().newInstance();AssetManager.class.getMethod("addAssetPath",String.class).invoke(assets,apk);
  Context c=new android.view.ContextThemeWrapper(original,android.R.style.Theme_Material_Dialog){public AssetManager getAssets(){return assets;}public Context getApplicationContext(){return this;}};
  c.getSharedPreferences("phone_secretary",0).edit().putBoolean(RadioModeManager.ENABLED,false).commit();RadioModeManager manager=new RadioModeManager(c);
  try{
   JSONObject data=new JSONObject().put("time","synthetic-test").put("place","現在地不明").put("movement","不明").put("recent_topics",new JSONArray()).put("already_covered",new JSONArray()).put("topic_mode","continuous").put("next_angle_hint","日常の雑学");
   Bitmap image=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(Color.WHITE);Paint ink=new Paint();ink.setColor(Color.BLUE);canvas.drawCircle(32,32,18,ink);ByteArrayOutputStream bytes=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.JPEG,85,bytes);image.recycle();
   byte[] pcm=new byte[32044];java.nio.ByteBuffer wav=java.nio.ByteBuffer.wrap(pcm).order(java.nio.ByteOrder.LITTLE_ENDIAN);wav.put("RIFF".getBytes("US-ASCII")).putInt(pcm.length-8).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put("data".getBytes("US-ASCII")).putInt(32000);
   JSONObject observation=new JSONObject().put("audio",Base64.encodeToString(pcm,2)).put("image",Base64.encodeToString(bytes.toByteArray(),2));
   for(int i=0;i<2;i++){JSONObject request=manager.buildRequest(data.toString(),i==0?observation:null);ok(!request.has("tools"),"no external operations");ok(request.getJSONArray("contents").getJSONObject(0).getJSONArray("parts").length()==(i==0?3:1),"actual multimodal/plain payload shape");ok(request.getJSONObject("generationConfig").getString("responseMimeType").equals("application/json"),"structured result");ok(request.toString().contains("全身443フレーム"),"actual identity profile included");try(FileOutputStream out=new FileOutputStream(new File(original.getFilesDir(),"provider-topic-v667-"+i+".json"))){out.write(request.toString().getBytes("UTF-8"));}}
   Method health=RadioModeManager.class.getDeclaredMethod("health",String.class,String.class);health.setAccessible(true);health.invoke(manager,"ERROR","WORK_TIMEOUT");JSONObject state=RadioModeManager.state(c);ok(state.getString("healthPhase").equals("ERROR")&&state.getString("healthReason").equals("WORK_TIMEOUT"),"timeout is visible over bridge");health.invoke(manager,"QUEUED","NONE");ok(RadioModeManager.state(c).getLong("lastProducedAt")>0,"successful generation time recorded");ok(RadioModeManager.state(c).getString("lastErrorReason").equals("WORK_TIMEOUT"),"last failure survives later success");for(int i=0;i<100;i++)health.invoke(manager,i%2==0?"WAITING":"CAPTURING","NONE");ok(new JSONArray(c.getSharedPreferences("phone_secretary",0).getString("radio_health_events","[]")).length()==64,"diagnostic ring bounded to 64 metadata-only entries");
   RadioObservationStore.begin("blocked-fixture",7);ok(RadioObservationStore.accept(new JSONObject().put("requestId","blocked-fixture").put("revision",7).put("blockedReason","CONVERSATION"),7,true),"busy capture receipt accepted without audio/photo");ok(RadioObservationStore.take("blocked-fixture").getString("blockedReason").equals("CONVERSATION"),"busy reason delivered instead of waiting 25 seconds");
  }finally{manager.close();}return n;
 }
}
